campus-bus-parser.source:
// Parses campus bus data, supporting "line" (route) and "vehicles" payloads.
function parse(rawJson) {
  var input = JSON.parse(rawJson);
  if (input.kind === 'line') return parseLine(input);
  if (input.kind === 'vehicles') return parseVehicles(input);
  throw new Error('Unsupported campus bus payload');
}

// Parses a bus route: stops with coordinates and basic line metadata.
function parseLine(input) {
  var data = input.data || {};
  var rawStops = Array.isArray(data.stops) ? data.stops : [];
  var stops = [];
  for (var i = 0; i < rawStops.length; i++) {
    var stop = rawStops[i] || {};
    var id = text(stop.stopId);
    var name = text(stop.stopName);
    // stopOrder = the stop's sequence index along the route.
    var index = integer(stop.stopOrder);
    // lng / lat = longitude / latitude of the stop.
    var lng = number(stop.lng);
    var lat = number(stop.lat);
    if (!id || !name || index === null || lng === null || lat === null) continue;
    stops.push({ id: id, name: name, index: index, lng: lng, lat: lat });
  }
  return JSON.stringify({
    schemaVersion: 1,
    kind: 'line',
    line: {
      lineId: text(data.lineId),
      // line2Id = the reverse-direction line id of the same route.
      oppositeLineId: text(data.line2Id),
      // lineNo = the human-readable line number (e.g. "校车1号线").
      lineNo: text(data.lineNo),
      // direction "0" means the default/forward direction.
      direction: text(data.direction) === '0',
      firstTime: text(data.firstTime),
      lastTime: text(data.lastTime),
      priceRange: text(data.price),
      stops: stops
    }
  });
}

// Parses a pipe-delimited vehicle list ("num|x|stationIndex|arrive|lon|lat").
function parseVehicles(input) {
  var raw = Array.isArray(input.vehicles) ? input.vehicles : [];
  var vehicles = [];
  for (var i = 0; i < raw.length; i++) {
    var parts = text(raw[i]).split('|');
    if (parts.length !== 6) continue;
    // parts[1] is unused (a placeholder "x" in the source payload).
    var stationIndex = integer(parts[2]);
    // arrive = "1" if the bus has arrived at the station, otherwise "0".
    var arrive = integer(parts[3]);
    var lon = number(parts[4]);
    var lat = number(parts[5]);
    if (stationIndex === null || arrive === null || lon === null || lat === null) continue;
    vehicles.push({
      // num = the vehicle identifier (e.g. bus plate number or code).
      num: text(parts[0]), stationIndex: stationIndex, arrive: arrive === 1,
      lon: lon, lat: lat
    });
  }
  vehicles.sort(function(a, b) { return a.stationIndex - b.stationIndex; });
  return JSON.stringify({ schemaVersion: 1, kind: 'vehicles', vehicles: vehicles });
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}
function integer(value) {
  var valueText = text(value);
  if (!/^-?\d+$/.test(valueText)) return null;
  var parsed = Number(valueText);
  return isFinite(parsed) ? parsed : null;
}
function number(value) {
  var valueText = text(value);
  if (!valueText) return null;
  var parsed = Number(valueText);
  return isFinite(parsed) ? parsed : null;
}

course-parser.source:
// Parses the academic system timetable (kbList) into a normalized course list.
function parse(rawJson) {
  var data = JSON.parse(rawJson);
  // kbList = 课表列表 (timetable list); courses from the academic system.
  var kbList = data.kbList || [];
  var result = [];

  for (var i = 0; i < kbList.length; i++) {
    var item = kbList[i];
    // kcmc = 课程名称 (course name).
    var title = sanitizeDisplay(item.kcmc || '');
    if (!title) continue;

    var weekday = parseWeekday(item.xqj, item.xqjmc);
    if (weekday < 1 || weekday > 7) continue;

    var classPeriod = parseClassPeriod(pickFirst(item, ['jcs', 'jc', 'jcsm']));
    if (!classPeriod) continue;

    var weeks = parseWeeks(pickFirst(item, ['zcd', 'zcmc', 'zc']));
    if (weeks.length === 0) continue;

    result.push({
      title: title,
      titleRaw: '' + (item.kcmc || ''),
      weekday: weekday,
      classFrom: classPeriod.from,
      classTo: classPeriod.to,
      weeks: weeks,
      // jxbmc = 教学班名称 code; teaching class id used as course id.
      courseId: (item.jxbmc || '').trim(),
      courseNature: sanitizeDisplay(pickFirst(item, ['kcxz', 'kcxzmc', 'kclbmc', 'kclb'])),
      // xm = 姓名 (teacher name).
      instructor: sanitizeDisplay(item.xm || ''),
      instructorRaw: '' + (item.xm || ''),
      // cdmc = 场地名称 (venue/room name).
      location: sanitizeDisplay(item.cdmc || ''),
      // zcd = 周次段 code; raw week-range string (e.g. "1-16周").
      weekMeta: (item.zcd || '').trim(),
      // kssj / jssj = 开始时间 / 结束时间 (start/end time).
      // sksj_kssj / sksj_jssj / kssj_hhmm are alternative field names.
      startText: pickFirst(item, ['kssj', 'sksj_kssj', 'kssj_hhmm']),
      endText: pickFirst(item, ['jssj', 'sksj_jssj', 'jssj_hhmm'])
    });
  }
  return JSON.stringify({ courses: result });
}

// Returns the first non-empty trimmed value among the given keys.
function pickFirst(obj, keys) {
  for (var i = 0; i < keys.length; i++) {
    var v = obj[keys[i]];
    if (v !== undefined && v !== null) {
      var s = ('' + v).trim();
      if (s.length > 0) return s;
    }
  }
  return '';
}

// Removes control/format/whitespace Unicode characters and collapses spaces.
function sanitizeDisplay(value) {
  return ('' + value)
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\u00ad\u200b-\u200f\u202a-\u202e\u2060\u2066-\u2069\ufeff]/g, '')
    .replace(/[\u00a0\u2000-\u200a\u202f\u205f]/g, ' ')
    .replace(/[ \t\f\v]+/g, ' ')
    .trim();
}

// Converts a weekday value to 1-7; falls back to matching Chinese day labels.
// xqj = 星期几 (weekday number), xqjmc = 星期几名称 code (weekday label).
function parseWeekday(raw, label) {
  if (raw !== undefined && raw !== null) {
    var n = parseInt(raw, 10);
    if (n >= 1 && n <= 7) return n;
  }
  var text = '' + (label || raw || '');
  if (text.indexOf('\u4e00') !== -1) return 1; // 一 (Mon)
  if (text.indexOf('\u4e8c') !== -1) return 2; // 二 (Tue)
  if (text.indexOf('\u4e09') !== -1) return 3; // 三 (Wed)
  if (text.indexOf('\u56db') !== -1) return 4; // 四 (Thu)
  if (text.indexOf('\u4e94') !== -1) return 5; // 五 (Fri)
  if (text.indexOf('\u516d') !== -1) return 6; // 六 (Sat)
  if (text.indexOf('\u65e5') !== -1 || text.indexOf('\u5929') !== -1 || text.indexOf('\u4e03') !== -1) return 7; // 日/天/七 (Sun)
  return -1;
}

// Parses a class period range like "1-2" into {from,to}; normalizes dashes.
// jc / jcs / jcsm = 节次 / 节次段 / 节次说明 (class period range).
function parseClassPeriod(text) {
  if (!text) return null;
  var raw = text.trim().replace(/\s+/g, '')
    .replace(/～/g, '-').replace(/~/g, '-').replace(/—/g, '-').replace(/－/g, '-');
  var nums = raw.match(/\d+/g);
  if (!nums || nums.length === 0) return null;
  var from = parseInt(nums[0], 10);
  var to = nums.length >= 2 ? parseInt(nums[1], 10) : from;
  if (from <= 0 || to < from) return null;
  return { from: from, to: to };
}

// Parses a week string like "1-16周,18周,单周" into a sorted unique week list.
// zcd / zcmc / zc = 周次段 code / 周次名称 code / 周次 (week range).
function parseWeeks(weekStr) {
  if (!weekStr) return [];
  var result = [];
  var parts = weekStr.split(/[,，;；、]/);
  for (var p = 0; p < parts.length; p++) {
    var seg = parts[p].trim();
    if (!seg) continue;
    var odd = seg.indexOf('\u5355') !== -1; // 单 (odd-week only)
    var even = seg.indexOf('\u53cc') !== -1; // 双 (even-week only)
    var nums = seg.match(/\d+/g);
    if (!nums) continue;
    var start = parseInt(nums[0], 10);
    var end = nums.length > 1 ? parseInt(nums[1], 10) : start;
    for (var w = start; w <= end; w++) {
      if (odd && w % 2 === 0) continue;
      if (even && w % 2 === 1) continue;
      if (result.indexOf(w) === -1) result.push(w);
    }
  }
  result.sort(function(a, b) { return a - b; });
  return result;
}

empty-room-parser.source:
// Parses empty-classroom availability data into a normalized room list.
function parse(rawJson) {
  var data = JSON.parse(rawJson);
  var result = data.data || [];
  if (!Array.isArray(result)) result = [];
  var rooms = [];
  for (var i = 0; i < result.length; i++) {
    var item = result[i];
    // jc = 节次 (class period), comma-separated section numbers like "1,2".
    var rawSections = (item.jc || '').toString();
    var sections = [];
    if (rawSections) {
      var parts = rawSections.split(',');
      for (var j = 0; j < parts.length; j++) {
        var n = parseInt(parts[j].trim(), 10);
        if (n > 0) sections.push(n);
      }
      sections.sort(function(a, b) { return a - b; });
    }
    rooms.push({
      // cdmc = 场地名称 (venue/room name).
      name: (item.cdmc || '').toString(),
      // jxl = 教学楼 (building).
      building: (item.jxl || '').toString(),
      // cdlb = 场地类别 (room type).
      type: (item.cdlb || '').toString(),
      // zws = 座位数 (total seat count).
      totalSeats: parseInt((item.zws || '').toString(), 10) || 0,
      // kszws = 可用座位数 (available seat count).
      availableSeats: parseInt((item.kszws || '').toString(), 10) || 0,
      availableSections: sections,
      // lh = 楼层 (floor).
      floor: (item.lh || '').toString()
    });
  }
  return JSON.stringify({ rooms: rooms });
}

graduate-course-parser.source:
// Normalizes newyjs xspkjgcx rows using the App graduate importer contract.
// Dates belong to the authenticated calendar, not to this pure parser.
function parse(rawJson) {
  var input = JSON.parse(rawJson);
  var rows = Array.isArray(input.rows) ? input.rows : [];
  var courses = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i] || {};
    var titleRaw = text(row.KCMC), title = display(titleRaw);
    var weekday = positive(row.XQ);
    if (text(row.XQ) === '0') weekday = 7;
    if (!title || weekday === null || weekday > 7) continue;
    var primary = text(row.ZCBH), secondary = text(row.ZCMC);
    var weeks = expandWeeks(primary || secondary);
    if (!weeks.length && primary && secondary && primary !== secondary) weeks = expandWeeks(secondary);
    if (!weeks.length) continue;
    var from = positive(row.KSJCDM), to = positive(row.JSJCDM);
    if (to === null) to = from;
    var start = clock(row.KSSJ), end = clock(row.JSSJ);
    if (!(from !== null && to >= from) && !(start && end)) continue;
    var cancelled = text(row.SFQZAP);
    if (cancelled === '1' || cancelled === 'true' || cancelled === '是') continue;
    var instructorRaw = text(row.JSXM);
    courses.push({
      title: title, titleRaw: titleRaw, courseId: text(row.KCDM), classId: text(row.BJDM),
      courseNature: display(text(row.KCLBDM_DISPLAY) || text(row.KCLBDM)),
      instructor: display(instructorRaw), instructorRaw: instructorRaw,
      location: display(text(row.JASMC)), weekday: weekday, weeks: weeks,
      weekMeta: secondary, classFrom: from === null ? -1 : from,
      classTo: to === null ? -1 : to, startText: start, endText: end
    });
  }
  return JSON.stringify({courses: courses});
}
function text(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function positive(v) { var m = text(v).match(/\d+/); return m && Number(m[0]) > 0 ? Number(m[0]) : null; }
function display(v) {
  return v.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\u00ad\u200b-\u200f\u202a-\u202e\u2060\u2066-\u2069\ufeff]/g, '')
    .replace(/[\u00a0\u2000-\u200a\u202f\u205f]/g, ' ').replace(/[ \t\f\v]+/g, ' ').trim();
}
function clock(v) {
  if (typeof v !== 'number' && !/^\d+$/.test(text(v))) return '';
  var n = Math.floor(Number(v));
  if (!isFinite(n) || n <= 0) return '';
  var hour = Math.floor(n / 100), minute = n % 100;
  if (!(hour <= 23 && minute <= 59)) {
    if (n >= 1440) return '';
    hour = Math.floor(n / 60); minute = n % 60;
  }
  return ('0' + hour).slice(-2) + ':' + ('0' + minute).slice(-2);
}
function expandWeeks(raw) {
  if (/^[01]{8,}$/.test(raw)) {
    var mask = []; for (var i = 0; i < raw.length; i++) if (raw.charAt(i) === '1') mask.push(i + 1);
    return mask;
  }
  var result = {}, pieces = raw.split(/[,，;；、\s]+/);
  for (var j = 0; j < pieces.length; j++) {
    var part = pieces[j], nums = part.match(/\d+/g);
    if (!nums || !nums.length) continue;
    var start = Number(nums[0]), end = Number(nums.length > 1 ? nums[1] : nums[0]);
    if (start <= 0 || end < start) continue;
    for (var w = start; w <= end; w++) {
      if (part.indexOf('单') >= 0 && w % 2 === 0) continue;
      if (part.indexOf('双') >= 0 && w % 2 === 1) continue;
      result[w] = true;
    }
  }
  return Object.keys(result).map(Number).sort(function(a, b) { return a - b; });
}

messages-parser.source:
// Parses campus notification/messages list data into a normalized message list.
function parse(rawJson) {
  var data = JSON.parse(rawJson);
  var resultData = data.resultData;
  if (!resultData) return JSON.stringify({ messages: [], totalCount: 0 });

  var rows = resultData.rows || [];
  var total = resultData.total || rows.length;
  var messages = [];
  for (var i = 0; i < rows.length; i++) {
    var item = rows[i];
    var msgId = (item.msgId || '').toString().trim();
    if (!msgId) continue;
    messages.push({
      msgId: msgId,
      // msgtitle = 消息标题 (message title).
      title: (item.msgtitle || '').toString(),
      summary: (item.summary || '').toString() || null,
      photoUrl: (item.photoUrl || '').toString() || null,
      senderName: (item.senderName || '').toString(),
      sendTime: (item.sendTime || '').toString(),
      sendMsgType: ((item.sendMsgType || '').toString() || '1'),
      // receiptStatus "1" or "2" means the message has been read.
      isRead: (item.receiptStatus || '').toString() === '1' || (item.receiptStatus || '').toString() === '2',
      appId: (item.appId || '').toString() || null
    });
  }
  return JSON.stringify({ messages: messages, totalCount: total });
}

score-parser.source:
// Parses raw score data from the academic system into a normalized score list.
function parse(rawJson) {
  var data = JSON.parse(rawJson);
  var items = data.items || [];
  var result = [];

  for (var i = 0; i < items.length; i++) {
    var item = items[i];

    // The academic system uses Hanyu Pinyin abbreviations for field names.
    // xnm = 学年名 (academic year), e.g. "2024".
    var xnmStr = (item.xnm || '').toString();
    // kcmc = 课程名称 (course name).
    var kcmc = (item.kcmc || '').toString().trim();
    // jsxm = 教师姓名 / jsxmmc = 教师姓名 名称 code; teacher name.
    var jsxm = (item.jsxm || item.jsxmmc || '').toString().trim();
    // jxbmc = 教学班名称 code; teaching class id used as course id.
    var jxbmc = (item.jxbmc || '').toString().trim();
    // xf = 学分 (credit).
    var xfStr = (item.xf || '').toString();
    // kcxzmc = 课程性质名称 code; course nature (e.g. 必修/选修).
    var kcxzmc = (item.kcxzmc || '').toString().trim();
    // bfzcj = 最终成绩 (final grade) raw value.
    var bfzcjStr = (item.bfzcj || '').toString();
    // kkbmmc = 开课部门名称 code; department offering the course.
    var kkbmmc = (item.kkbmmc || '').toString().trim();
    // xqm = 学期名 (semester code, see below).
    var xqmStr = (item.xqm || '').toString();
    // cjbz = 成绩标志 (grade status); "中期退课" means midterm withdrawal.
    var cjbz = (item.cjbz || '').toString();
    // ksxz / ksxzmc = 考试性质 / 考试性质名称 (exam type).
    var examType = ((item.ksxz || item.ksxzmc || '') + '' || '正常考试').trim();

    var yearVal = parseInt(xnmStr, 10) || -1;
    var credit = parseFloat(xfStr);

    // Map the academic system's semester code to 1/2/3 (3 => 1, 12 => 2, 16 => 3).
    var rawSemester = parseInt(xqmStr, 10) || -1;
    var normalizedSemester = 1;
    if (rawSemester === 3) normalizedSemester = 1;
    else if (rawSemester === 12) normalizedSemester = 2;
    else if (rawSemester === 16) normalizedSemester = 3;

    // A midterm withdrawal is flagged either by cjbz or by cj === 'W'.
    // cj = 成绩 (grade) raw value, used here only for the 'W' case.
    var isMidtermWithdraw = cjbz === '\u4e2d\u671f\u9000\u8bfe' || (item.cj || '').toString() === 'W';
    var parsedScore = parseInt(bfzcjStr, 10);

    // Skip rows without a valid year/credit, or without a score (unless withdrawn).
    if (yearVal <= 0 || isNaN(credit)) continue;
    if (isNaN(parsedScore) && !isMidtermWithdraw) continue;

    result.push({
      year: yearVal,
      semester: normalizedSemester,
      name: kcmc,
      instructor: jsxm,
      courseId: jxbmc,
      credit: credit,
      courseType: kcxzmc,
      score: isNaN(parsedScore) ? 0 : parsedScore,
      courseCollege: kkbmmc,
      isSpoiler: isMidtermWithdraw,
      spoilerLabel: isMidtermWithdraw ? '\u4e2d\u671f\u9000\u8bfe' : null,
      examType: examType
    });
  }
  return JSON.stringify({ scores: result });
}

study-status-course-parser.source:
// Parses study-status course data (credit/score/status) into a course list.
// Handles retake scores (CXCJ1) and makeup exams (CXCJ) by choosing the max.
function parse(rawJson) {
  var data = JSON.parse(rawJson);
  var items = data.items || data;
  if (!Array.isArray(items)) items = [];
  var result = [];
  for (var i = 0; i < items.length; i++) {
    var item = items[i];
    // The study-status API uses UPPERCASE Pinyin abbreviations for fields.
    // XDZT = 学位状态 (status code, see parseStatus).
    var xdzt = (item.XDZT || '').toString();
    var status = parseStatus(xdzt);
    // CJ = 成绩 (grade raw value).
    var score = (item.CJ || '').toString();
    // CXCJ1 = 重修成绩 (retake grade, if any).
    var retakeScoreStr = (item.CXCJ1 || '').toString();
    var maxScoreStr = (item.MAXCJ || '').toString();
    // JD = 绩点 (grade point).
    var jd = (item.JD || '').toString();
    // XF = 学分 (credit).
    var xf = (item.XF || '').toString();

    var hasRetake = item.hasOwnProperty('CXCJ1');
    var originalScore = parseInt(score, 10);
    var retakeScore = parseInt(retakeScoreStr, 10);
    var maxScore = parseInt(maxScoreStr, 10);
    // Prefer the max score if available; otherwise retake, otherwise original.
    var effectiveScore = !isNaN(maxScore) ? maxScore : (hasRetake ? retakeScore : originalScore);

    result.push({
      // KCMC = 课程名称 (course name).
      name: (item.KCMC || '').toString(),
      // KCXZMC = 课程性质名称 code (course nature, e.g. 必修/选修).
      category: (item.KCXZMC || '').toString(),
      credit: parseFloat(xf) || 0,
      score: isNaN(effectiveScore) ? null : effectiveScore,
      gradePoint: parseFloat(jd) || null,
      maxScore: isNaN(maxScore) ? null : maxScore,
      status: status,
      // XSXXXX = 学时信息 (class hours).
      hours: (item.XSXXXX || '').toString() || null,
      // KCLBMC = 课程类别名称 code (course category).
      courseNature: (item.KCLBMC || '').toString() || null,
      // JYXDXNMC = 培养方案学年名称 code (suggested academic year).
      suggestedYear: (item.JYXDXNMC || '').toString() || null,
      // JYXDXQMC = 培养方案学期名称 code (suggested semester).
      suggestedSemester: (item.JYXDXQMC || '').toString() || null,
      // KCZYXXS = 课程专业信息数 (importance, a numeric weight).
      importance: parseFloat((item.KCZYXXS || '').toString()) || null,
      // KCYWMC = 课程英文名称 code (course English name).
      englishName: (item.KCYWMC || '').toString() || null,
      // KCH = 课程号 (course code).
      courseCode: (item.KCH || '').toString() || null,
      // XNMC = 学年名称 code (academic year of the row).
      academicYear: (item.XNMC || '').toString() || null,
      // XQMMC = 学期名称 code (semester of the row).
      semester: (item.XQMMC || '').toString() || null,
      // CXCJ = 重修成绩 (makeup/retake exam presence flag).
      hasMakeupExam: item.hasOwnProperty('CXCJ'),
      hasRetake: hasRetake,
      originalScore: isNaN(originalScore) ? null : originalScore,
      retakeScore: isNaN(retakeScore) ? null : retakeScore
    });
  }
  return JSON.stringify({ courses: result });
}

// Maps the academic system status code to a readable status.
function parseStatus(xdzt) {
  if (xdzt === '4') return 'passed';
  if (xdzt === '2') return 'failed';
  if (xdzt === '1') return 'studying';
  return 'notTaken';
}

study-status-index-parser.source:
// Parses the study-status index page HTML into ids, names, modes, credits,
// and a credit-requirement tree.
//
// The page embeds credit requirements via HTML attributes using Pinyin
// abbreviations: xfyqjd_id = 学分要求节点_id (requirement node id),
// fxfyqjd_id = 父学分要求节点_id (parent node id),
// jdkcsx = 节点课程属性 (requirement type),
// yxxf = 已修学分 (earned credits), yqzdxf = 要求最低学分 (min required credits).
function parse(rawJson) {
  var input = JSON.parse(rawJson);
  var html = typeof input.html === 'string' ? input.html : '';

  var ids = discoverIds(html);
  var names = input.names || discoverNames(html);
  var modes = discoverModes(html);
  var credits = input.credits || discoverCredits(html);
  var tree = buildTree(html, names, credits);

  return JSON.stringify({
    ids: ids,
    names: names,
    modes: modes,
    credits: credits,
    tree: tree
  });
}

// Collects all requirement ids (plus two synthetic fixed ids) from the page.
function discoverIds(html) {
  var pattern = /xfyqjd_id='([A-F0-9]{32})'/g;
  var ids = {};
  var m;
  while ((m = pattern.exec(html)) !== null) {
    ids[m[1]] = true;
  }
  var result = Object.keys(ids);
  // qtkcxfyq = 其他课程学分要求 / cxcyqkxfyq = 创新创业区学分要求 (scope ids).
  result.push('qtkcxfyq', 'cxcyqkxfyq');
  return result;
}

// Maps requirement ids to their display names by reading <p class='title1'>.
function discoverNames(html) {
  var result = {};
  var pattern = /<p class='title1' id='p([A-F0-9]{32})'/g;
  var m;
  while ((m = pattern.exec(html)) !== null) {
    var id = m[1];
    var closeIdx = html.indexOf('>', m.index + m[0].length);
    if (closeIdx === -1) continue;
    var nbspIdx = html.indexOf('&nbsp;', closeIdx);
    if (nbspIdx === -1) continue;
    var raw = html.substring(closeIdx + 1, nbspIdx);
    var lastQuote = raw.lastIndexOf('"');
    if (lastQuote !== -1) raw = raw.substring(lastQuote + 1);
    var name = raw.trim();
    if (name.length > 0 && name.indexOf('get(') === -1) {
      result[id] = name;
    }
  }
  return result;
}

// Maps requirement ids to their requirement type code (jdkcsx = 节点课程属性).
function discoverModes(html) {
  var result = {};
  var pattern = /xfyqjd_id='([A-F0-9]{32})' jdkcsx='([0-9]+)'/g;
  var m;
  while ((m = pattern.exec(html)) !== null) {
    if (!result[m[1]]) result[m[1]] = m[2];
  }
  return result;
}

// Maps requirement ids to earned/required credit pairs (yxxf / yqzdxf).
// yxxf = 已修学分, yqzdxf = 要求最低学分.
function discoverCredits(html) {
  var result = {};
  var pattern = /id='p([A-F0-9]{32})' yxxf='([0-9.]+)' yqzdxf='([0-9.]+)'/g;
  var m;
  while ((m = pattern.exec(html)) !== null) {
    if (!result[m[1]]) {
      result[m[1]] = {
        earnedCredits: parseFloat(m[2]) || 0,
        requiredCredits: parseFloat(m[3]) || 0
      };
    }
  }
  return result;
}

// Reconstructs the parent/child relationships between credit requirements.
// Relationships can be encoded either as li attributes or .appendTo calls.
// fxfyqjd_id = 父学分要求节点_id (parent node id).
function buildTree(html, idToName, idToCredits) {
  var childToParent = {};
  var discoveredIds = {};

  var liPattern = /<li\b[^>]*>/g;
  // liIdPattern = id='li...' form; childAttrPattern = xfyqjd_id form.
  var liIdPattern = /\bid='li([A-F0-9]{32})'/;
  var childAttrPattern = /\bxfyqjd_id='([A-F0-9]{32})'/;
  var parentAttrPattern = /\bfxfyqjd_id='([A-F0-9]{32})'/;

  var m;
  // Strategy 1: derive parent-child from li attributes on the same element.
  while ((m = liPattern.exec(html)) !== null) {
    var li = m[0];
    var childIdMatch = liIdPattern.exec(li) || childAttrPattern.exec(li);
    if (!childIdMatch) continue;
    var childId = childIdMatch[1];
    discoveredIds[childId] = true;

    var parentMatch = parentAttrPattern.exec(li);
    if (parentMatch && parentMatch[1] !== childId) {
      if (!childToParent[childId]) childToParent[childId] = parentMatch[1];
      discoveredIds[parentMatch[1]] = true;
    }
  }

  var appendToPattern = /\.appendTo\(\$\((['\"])#ul([A-F0-9]{32})\1\)\)/g;
  var pIdPattern = /<p class='title1' id='p([A-F0-9]{32})'/g;

  // Strategy 2: derive parent-child from .appendTo(#ul...) calls; the child
  // name is the last title preceding the appendTo call.
  while ((m = appendToPattern.exec(html)) !== null) {
    var parentId = m[2];
    var previousHtml = html.substring(0, m.index);
    var pMatches = [];
    var pm;
    pIdPattern.lastIndex = 0;
    while ((pm = pIdPattern.exec(previousHtml)) !== null) {
      pMatches.push(pm);
    }
    if (pMatches.length === 0) continue;
    var childId2 = pMatches[pMatches.length - 1][1];
    discoveredIds[childId2] = true;
    discoveredIds[parentId] = true;
    if (childId2 !== parentId && !childToParent[childId2]) {
      childToParent[childId2] = parentId;
    }
  }

  // Build a parent -> children mapping for every known id.
  var parentToChildren = {};
  var allIds = {};
  var k;
  for (k in idToName) allIds[k] = true;
  for (k in discoveredIds) allIds[k] = true;
  for (k in allIds) parentToChildren[k] = [];

  for (var child in childToParent) {
    var parent = childToParent[child];
    if (!parentToChildren[parent]) parentToChildren[parent] = [];
    if (parentToChildren[parent].indexOf(child) === -1) {
      parentToChildren[parent].push(child);
    }
    if (!parentToChildren[child]) parentToChildren[child] = [];
  }

  // Roots are named nodes that are never a child.
  var childSet = {};
  for (var c in childToParent) childSet[c] = true;

  var rootIds = [];
  for (var id in parentToChildren) {
    if (idToName[id] && !childSet[id]) rootIds.push(id);
  }

  // Depth-first build with cycle detection via the visiting set.
  var visiting = {};
  function buildNode(id) {
    if (visiting[id]) {
      return { name: idToName[id] || id, requiredCredits: 0, earnedCredits: 0, children: [] };
    }
    visiting[id] = true;
    var children = (parentToChildren[id] || [])
      .filter(function(cid) { return idToName[cid]; })
      .map(buildNode);
    delete visiting[id];
    var credits = idToCredits[id] || {};
    return {
      name: idToName[id] || id,
      requiredCredits: credits.requiredCredits || 0,
      earnedCredits: credits.earnedCredits || 0,
      children: children
    };
  }

  return rootIds.map(buildNode);
}
